-- 线性表进阶：顺序表与链表的操作边界比较。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '顺序表与链表的取舍','顺序表擅长随机访问，链表在已知前驱时局部插删更直接；选择应基于操作模式。',course.id,parent.id,'cs408-sequential-vs-linked','AISTU',1,'REVIEWED',10,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-sequential-vs-linked' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-sequential-vs-linked',1,'REVIEWED','顺序表与链表的取舍',JSON_OBJECT('summary','顺序表按下标随机访问为 O(1)，但中间插删需移动元素且扩容可能重分配；链表按位定位通常为 O(n)，但已知前驱或邻近位置时局部插删为 O(1)。选择表示应匹配实际操作模式，也要考虑指针空间和缓存局部性。','steps',JSON_ARRAY('顺序表用首地址和下标直接定位','中间插删会移动后续连续元素','链表按位置访问需要沿指针寻找','已知前驱时链表局部改接为 O(1)','复杂度结论必须附带操作前提'),'prerequisite',JSON_OBJECT('contentKey','cs408-sequential-list-storage','title','顺序表的连续存储','description','先理解顺序表为何可以按下标直接定位。')),JSON_OBJECT('id','sequential-vs-linked-v1','prompt','若需要频繁按下标随机读取，通常应优先考虑哪种表示？','options',JSON_ARRAY(JSON_OBJECT('id','OPERATION_PROFILE','text','顺序表，因为下标可直接计算地址'),JSON_OBJECT('id','ALWAYS_LINKED','text','链表，因为每次读取都不需要连续空间')),'correctOptionId','OPERATION_PROFILE','correctExplanation','正确：随机读取是顺序表的直接优势；结构选择应依据主要操作。','incorrectExplanation','不正确：链表按逻辑位置读取仍须沿 next 遍历。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-sequential-vs-linked' AND existing.content_version=1 WHERE point.content_key='cs408-sequential-vs-linked' AND existing.id IS NULL;
